{"function": "() => {
  const articles = [];
  // Find the main article containing the rules
  const articleElement = document.querySelector('article');
  if (!articleElement) return articles;

  // Get all list items that contain article headings
  const listItems = articleElement.querySelectorAll('li');

  let currentArticle = null;

  for (const li of listItems) {
    // Check if this li contains article text (starts with "ARTICLE")
    const textNodes = Array.from(li.childNodes).filter(n => n.nodeType === Node.TEXT_NODE);
    const articleText = textNodes.map(n => n.textContent.trim()).join(' ').trim();

    if (articleText && articleText.startsWith('ARTICLE')) {
      // This is an article heading
      currentArticle = {
        designation: articleText.split('.')[0].trim(), // "ARTICLE I"
        title: articleText.split('.').slice(1).join('.').trim(), // "GENERAL PROVISIONS"
        rules: []
      };
      articles.push(currentArticle);

      // Find nested list of rules within this li
      const nestedList = li.querySelector('ul');
      if (nestedList) {
        const ruleItems = nestedList.querySelectorAll('li');
        for (const ruleLi of ruleItems) {
          const link = ruleLi.querySelector('a');
          const linkText = link ? link.textContent.trim() : '';
          const afterLinkText = Array.from(ruleLi.childNodes)
            .filter(n => n.nodeType === Node.TEXT_NODE)
            .map(n => n.textContent.trim())
            .join(' ')
            .trim();

          const ruleNumber = linkText.replace('Rule ', '').trim();
          const ruleTitle = afterLinkText.startsWith('.') ? afterLinkText.substring(1).trim() : afterLinkText;

          if (ruleNumber) {
            currentArticle.rules.push({
              number: ruleNumber,
              title: ruleTitle
            });
          }
        }
      }
    }
  }

  return articles;
}"}

