  // Find the paragraph with "These are the Federal Rules of Evidence"
  const paragraphs = Array.from(document.querySelectorAll('p'));
  const targetParagraph = paragraphs.find(p => p.textContent.includes('These are the Federal Rules of Evidence'));

  if (!targetParagraph) return 'Paragraph not found';

  // Find the next sibling that is a list
  let nextElem = targetParagraph.nextElementSibling;
  while (nextElem && nextElem.tagName.toLowerCase() !== 'ul') {
    nextElem = nextElem.nextElementSibling;
  }

  if (!nextElem) return 'List not found';

  // Now parse this list
  const articles = [];
  let currentArticle = null;

  // Process list items
  const listItems = nextElem.querySelectorAll('li');
  for (const li of listItems) {
    // Get direct text child (article heading)
    const textNodes = Array.from(li.childNodes).filter(n => n.nodeType === Node.TEXT_NODE);
    const articleText = textNodes.map(n => n.textContent.trim()).join(' ').trim();

