{"function": "() => {
  const article = document.querySelector('article');
  if (!article) return null;

  // Get text content, preserving line structure
  const walker = document.createTreeWalker(article, NodeFilter.SHOW_TEXT);
  const lines = [];
  let currentNode;
  while (currentNode = walker.nextNode()) {
    const text = currentNode.textContent.trim();
    if (text) {
      lines.push(text);
    }
  }

  // Parse articles and rules
  const articles = [];
  let currentArticle = null;
  let i = 0;

  while (i < lines.length) {
    const line = lines[i];

    // Check if line starts with "ARTICLE"
    if (line.startsWith('ARTICLE')) {
      // Extract designation and title
      const dotIndex = line.indexOf('.');
      const designation = dotIndex !== -1 ? line.substring(0, dotIndex).trim() : line;
      const title = dotIndex !== -1 ? line.substring(dotIndex + 1).trim() : '';

      currentArticle = {
        designation,
        title,
        rules: []
      };
      articles.push(currentArticle);
      i++;
    } 
    // Check if line starts with "Rule" (rule number)
    else if (line.startsWith('Rule')) {
      if (!currentArticle) {
        // Should not happen but handle gracefully
        currentArticle = {
          designation: 'UNKNOWN',
          title: '',
          rules: []
        };
        articles.push(currentArticle);
      }

      const ruleNumber = line.substring(4).trim(); // Remove "Rule "

      // Next line should be the title starting with "."
      i++;
      if (i < lines.length) {
        let ruleTitle = lines[i];
        // Remove leading dot and space if present
        if (ruleTitle.startsWith('.')) {
          ruleTitle = ruleTitle.substring(1).trim();
        }

        currentArticle.rules.push({
          number: ruleNumber,
          title: ruleTitle
        });
        i++;
      } else {
        // No title line, just add rule number
        currentArticle.rules.push({
          number: ruleNumber,
          title: ''
        });
        i++;
      }
    } else {
      // Skip any other lines
      i++;
    }
  }

  return articles;
}"}

