  // Parse this list
  const articles = [];
  let currentArticle = null;

  // Get all list items (direct children or nested)
  // Actually, we need to traverse the structure properly
  // The list may have li elements or div with role="listitem"
  const items = targetList.querySelectorAll('li, [role="listitem"]');

  for (const item of items) {
    // Get text nodes that are direct children (article heading)
    const textNodes = Array.from(item.childNodes).filter(n => n.nodeType === Node.TEXT_NODE);
    const articleText = textNodes.map(n => n.textContent.trim()).join(' ').trim();

