      currentArticle = {
        designation,
        title,
        rules: []
      };
      articles.push(currentArticle);

      // Find nested list within this item
      let nestedList = item.querySelector('ul, ol, [role="list"]');
      if (!nestedList) {
        // Maybe the nested list is a sibling? Let's check next element
        let next = item.nextElementSibling;
        while (next && !next.textContent.includes('Rule')) {
