function.arguments:
{"function": "() => {
    const allParas = Array.from(document.querySelectorAll('p'));
    let startIndex = -1;
    for (let i = 0; i < allParas.length; i++) {
        if (allParas[i].textContent.includes('Committee Notes on Rules—2011 Amendment')) {
            startIndex = i;
            break;
        }
    }
    if (startIndex === -1) return '';
    let endIndex = startIndex + 1;
    // find next paragraph that starts with 'Committee Notes on Rules—' or 'Notes of Advisory Committee'
    for (let j = startIndex + 1; j < allParas.length; j++) {
        if (allParas[j].textContent.includes('Committee Notes on Rules—') || 
            allParas[j].textContent.includes('Notes of Advisory Committee')) {
            endIndex = j;
            break;
        }
    }
    // collect paragraphs from startIndex to endIndex-1
    let text = '';
    for (let k = startIndex; k < endIndex; k++) {
        text += allParas[k].textContent.trim() + '\n\n';
    }
    return text.trim();
}"}

