function.arguments:
{"function": "() => {
    const heading = Array.from(document.querySelectorAll('p')).find(p => p.textContent.includes('Committee Notes on Rules—2011 Amendment'));
    if (!heading) return '';
    let content = '';
    let node = heading;
    while (node) {
        content += node.textContent.trim() + '\n\n';
        node = node.nextElementSibling;
        if (!node || node.tagName !== 'P') break;
        // stop if next paragraph is another committee note heading
        if (node.textContent.includes('Committee Notes on Rules—') || node.textContent.includes('Notes of Advisory Committee')) {
            break;
        }
    }
    return content.trim();
}"}

